'use strict';
const el=id=>document.getElementById(id);let index=[];
function showAppendix(id){const entry=index.find(e=>e.id===id)||index[0];if(!entry)return;const hash=location.hash;el('appendixTitle').textContent=`Appendix ${entry.id} · ${entry.title}`;el('appendixFrame').src=`./bullinger/appendices/${entry.id}.html${hash}`;el('fullPage').href=`./bullinger/appendices/${entry.id}.html${hash}`;el('originalSource').href=entry.source;document.querySelectorAll('[data-appendix]').forEach(a=>a.setAttribute('aria-current',a.dataset.appendix===entry.id?'page':'false'))}
function renderIndex(){const list=el('appendixList');list.replaceChildren();const needle=el('appendixFilter').value.toLowerCase().trim();let count=0;for(const entry of index){if(needle&&!`${entry.id} ${entry.title}`.toLowerCase().includes(needle))continue;count++;const a=document.createElement('a');a.href=`?n=${entry.id}`;a.dataset.appendix=entry.id;const n=document.createElement('b');n.textContent=entry.id;a.append(n,document.createTextNode(entry.title));a.onclick=e=>{e.preventDefault();history.pushState({},'',a.href);showAppendix(entry.id)};list.append(a)}if(!count)list.textContent='No matching appendices. Try a number or another word.'}
fetch('./bullinger/appendix-index.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(data=>{index=data.appendices;el('coverage').textContent=`${data.standardAppendices} numbered appendices, plus supplementary tables and maps. All included locally.`;el('appendixFilter').oninput=renderIndex;renderIndex();showAppendix(new URLSearchParams(location.search).get('n')?.toUpperCase());window.onpopstate=()=>showAppendix(new URLSearchParams(location.search).get('n')?.toUpperCase())}).catch(()=>{el('coverage').textContent='The appendix files could not be loaded. Serve the complete app folder over HTTP.'});
